/* eslint-disable no-unused-vars */
import React, { useEffect, useRef, useState } from 'react';
import './App.css';
import { Stages } from './Stages';

function fetchQuestionsAndAnswers(setQuestions, setShuffledAnswers) {
    return async () => {
      try {
        const response = await fetch('/home');
        const data = await response.json();
        setQuestions(data.questions);
        shuffleAnswers(data.answers, setShuffledAnswers);
      } catch (error) {
        console.error('Error fetching data:', error);
      }
    };
  }
  
  function shuffleAnswers(answers, setShuffledAnswers) {
    if (answers.length > 0) {
      const shuffled = [...answers[0].wrong, answers[0].right].sort(() => Math.random() - 0.5);
      setShuffledAnswers(shuffled);
    }
  }
  
  export function Main() {
    const [selectedAnswer, setSelectedAnswer] = useState(null);
    const [radioSymbol, setRadioSymbol] = useState("◇");
    const [questions, setQuestions] = useState([]);
    const [shuffledAnswers, setShuffledAnswers] = useState([]);
  
    const videoRef = useRef(null);
    let stageCounter = 1;
  
    useEffect(() => {
      const fetchData = fetchQuestionsAndAnswers(setQuestions, setShuffledAnswers);
      fetchData();
      if (videoRef.current) {
        const video = videoRef.current;
        video.play();
        setTimeout(() => {
          video.classList.add('remove');
        }, 2000);
      }
    }, []);
  
    const handleAnswerClick = (event) => {
        const selectedDiv = event.currentTarget;
      
        // Remove 'selected' class from all answer divs
        const answerDivs = document.querySelectorAll('.answer');
        answerDivs.forEach(div => {
          div.classList.remove('selected');
        });
      
        // Add 'selected' class to the clicked answer div
        selectedDiv.classList.add('selected');
      
        // Reset radioSymbol for all answer divs
        const allAnswerDivs = document.querySelectorAll('.answer');
        allAnswerDivs.forEach(div => {
          const radioButton = div.querySelector('input[type="radio"]');
          if (radioButton) {
            const symbol = div === selectedDiv ? '◈' : '◇';
            setRadioSymbol(prevSymbol => ({
              ...prevSymbol,
              [radioButton.id]: symbol,
            }));
          }
        });
      
        // Find the radio button inside the clicked answer div and trigger a click event
        const radioButton = selectedDiv.querySelector('input[type="radio"]');
        if (radioButton) {
          radioButton.checked = true;
          setSelectedAnswer(radioButton.id);
        }
      };

  return (
    <div className="bkgr" id="bkgr3">
      <video className="video" ref={videoRef} id="open_curt" autoPlay muted>
        <source src="/Img/open_curt.webm" type="video/webm" />
      </video>
      <Stages />
      <form className="main_game" id="game_continue">
        <div className="question">{questions.length > 0 ? questions[0] : ''}</div>
        <div className="answer_cont">
          <fieldset>
            {shuffledAnswers.map((answer, index) => (
              <div className="answer" key={`answer_${index}`} onClick={handleAnswerClick}>
                <span className="answer_letter">{radioSymbol}</span>
                <input type="radio" id={`Answer_${index}`} name="answers"></input>
                <label htmlFor={`Answer_${index}`}>{answer}</label>
              </div>
            ))}
          </fieldset>
        </div>
        <div className="line2"></div>
        <div className="option_cont">
          <div className="help_cont">
            <div className="help" id="fifty"></div>
            <div className="help used" id="people"></div>
            <div className="help" id="refresh"></div>
          </div>
          <input type='submit' className="check_btn" value="Submit answer"></input>
        </div>
        <div className="line2"></div>
      </form>
    </div>
  );
}
